            if node.right.value == 0:
                self.emit("PUSH", 0)
            else:
                bits = bin(node.right.value)[3:]
                self.expression(node.left)
                for bit in bits:
                    self.emit("DUP"); self.emit("ADD")
                    if bit == "1":
