CASES_EXISTING = [(b"", [], "NONE", ())]
CASES_FEATURE = [
    (b"(ab|c)+", [b"ab", b"ccab", b"ac"], "NONE", (b"ab", b"ccab")),
    (b"[^a-c]+", [b"def", b"ABC", b""], "ASCII_IGNORE_CASE", (b"def",)),
    (b"a" * 64, [b"a" * 64, b"a" * 63], "NONE", (b"a" * 64,)),
